import{_ as t,o,c as a,a2 as i}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"UXD-003 — Home route-card titles are upright Space Mono; the 4.5 px icon text stays deleted","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-003-home-route-card-titles-upright.md","filePath":"uxs/decisions/UXD-003-home-route-card-titles-upright.md"}'),r={name:"uxs/decisions/UXD-003-home-route-card-titles-upright.md"};function s(n,e,l,c,d,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="uxd-003-—-home-route-card-titles-are-upright-space-mono-the-4-5-px-icon-text-stays-deleted" tabindex="-1">UXD-003 — Home route-card titles are upright Space Mono; the 4.5 px icon text stays deleted <a class="header-anchor" href="#uxd-003-—-home-route-card-titles-are-upright-space-mono-the-4-5-px-icon-text-stays-deleted" aria-label="Permalink to &quot;UXD-003 — Home route-card titles are upright Space Mono; the 4.5 px icon text stays deleted&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted</li><li><strong>Date</strong>: 2026-11-11 (proposed and decided)</li><li><strong>Decider</strong>: the operator — &quot;A1 follow-up (operator 2026-11-11): home route-card titles stay upright Space Mono (option a; were Crimson italic)&quot; (<code>docs/wip/2026-11-11-ux-feedback-plan.md</code> line 431)</li><li><strong>Answers</strong>: H8 (partly), X1; slice A1 (type scale); full home styling is slice F3</li><li><strong>Changes</strong>: IA §home-cards; UXS-013 (landing page typography). <em>Rules to be updated to link here (UXS-000 §Next).</em></li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>During the A1 type-scale slice the home route cards were the one place where the new rule (<a href="./UXD-002-type-scale-and-the-11px-floor">UXD-002</a>: no italic outside quotes and captions) and the existing look (card titles in Crimson italic) collided. The A1 brief had already ruled &quot;Home <code>.tagline</code>, <code>.prose p</code>, card titles: CHANGE now (no partial updates)&quot; (<code>docs/wip/2026-11-11-slice-A1-brief.md</code> line 26). The route-card icons also carried a 4.5 px &quot;T+254 d&quot; text, far under the 11 px floor.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><p>The source names &quot;option a&quot; (upright Space Mono) and says the titles &quot;were Crimson italic&quot;. The other options offered, and the review sheet that showed them, are not in the repository.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Home route-card titles are <strong>upright Space Mono</strong> (option a), not Crimson. The 4.5 px &quot;T+254 d&quot; text on the route-card icons <strong>stays deleted</strong> (plan line 431). All other home styling is <strong>not</strong> settled here: it is decided in the home-page slice, covering &quot;every aspect of the page&quot; (plan line 431; point H8, &quot;revisit with the rest of the page&quot;, plan line 134).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The Home hero, tagline and the remaining typography stay open until the home slice (F3 in the slice plan: H1, H2, H3; and the operator decisions D1 to D3, which are open, see UXS-000 §Open).</li><li>IA §home-cards and UXS-013 must say upright Space Mono for route-card titles, and must not describe the deleted icon text.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Covered by the type-floor and italic rules of UXD-002 (<code>tests/e2e/type-floor.spec.ts</code>), which checks size and the label colour on the landing; it does not assert the card-title face specifically. Not verified by this document.</p>',12)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
